        vec![
            Layout::horizontal([Constraint::Ratio(1, 2), Constraint::Ratio(1, 2)]).split(areas[2])
                [1],
        ]
    } else {
        Layout::horizontal(
            buttons
                .iter()
                .map(|_| Constraint::Ratio(1, buttons.len() as u32))
                .collect::<Vec<_>>(),
        )
        .split(areas[2])
        .iter()
        .copied()
        .collect()
    };
    for ((label, selected), area) in buttons.iter().zip(&hits) {
