fn resolve_path(query: &str, home: &Path, current: &Path) -> PathBuf {
    if query == "~" {
        home.to_path_buf()
    } else if let Some(rest) = query.strip_prefix("~/") {
        home.join(rest)
    } else if Path::new(query).is_absolute() {
        PathBuf::from(query)
    } else {
        current.join(query)
    }

