fn move_tree_selection(tree: &[(PathBuf, usize)], cursor: &mut PathBuf, delta: isize) {
    let index = tree
        .iter()
        .position(|(path, _)| path == cursor)
        .unwrap_or(0);
    let next = index
        .saturating_add_signed(delta)
        .min(tree.len().saturating_sub(1));
    if let Some((path, _)) = tree.get(next) {
        *cursor = path.clone();
    }

