fn progress_frame(
    frame: &mut Frame,
    label: &str,
    ratio: f64,
    title: &str,
    dry_run: bool,
    output: &[String],
) {
    let areas = Layout::vertical([
        Constraint::Length(3),
        Constraint::Length(5),
        Constraint::Min(3),
        Constraint::Length(3),
        Constraint::Length(1),
    ])
    .split(frame.area());
    frame.render_widget(
        Paragraph::new(if dry_run {
            " Foundry OpenCode  /  DRY-RUN SIMULATION"
        } else {
            " Foundry OpenCode  /  Working"
        })
        .style(
            Style::default()
                .fg(Color::Cyan)
                .add_modifier(Modifier::BOLD),
        ),
        areas[0],
    );
    frame.render_widget(
        Paragraph::new(format!(
            "{label}\n\n{}",
            if dry_run {
                "Mock timing only; no actions are performed."
            } else {
                "Please keep this window open."
            }
        ))
        .wrap(Wrap { trim: false })
        .block(Block::default().borders(Borders::ALL).title("Current step")),
        areas[1],
    );
    frame.render_widget(
        Paragraph::new(
            output
                .iter()
                .rev()
                .take(areas[2].height.saturating_sub(2) as usize)
                .rev()
                .cloned()
                .collect::<Vec<_>>()
                .join("\n"),
        )
        .block(
            Block::default()
                .borders(Borders::ALL)
                .title("Terminal output"),
        ),
        areas[2],
    );
    frame.render_widget(
        Gauge::default()
            .block(Block::default().title(title).borders(Borders::ALL))
            .ratio(ratio.clamp(0.0, 1.0))
            .gauge_style(Style::default().fg(Color::Cyan)),
        areas[3],
    );
    frame.render_widget(
        Paragraph::new(if dry_run {
            " Preview only: no install/removal commands, browser, or files changed."
        } else {
            " Please keep this window open until installation completes."
        })
        .style(Style::default().fg(Color::Gray)),
        areas[4],
    );

