fn release_version(value: &str) -> eyre::Result<&str> {
    let version = value
        .strip_prefix('v')
        .ok_or_else(|| eyre::eyre!("Unexpected release tag"))?;
    eyre::ensure!(
        version.split('.').count() == 3
            && version
                .split('.')
                .all(|p| !p.is_empty() && p.bytes().all(|b| b.is_ascii_digit())),
        "Unexpected release tag"
    );
    Ok(version)
}

