pub fn backup_path(path: &Path) -> PathBuf {
    let stamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    path.with_file_name(format!(
        "{}.backup-{}-{stamp}-{}",
        path.file_name().unwrap().to_string_lossy(),
        std::process::id(),
        NEXT_PATH.fetch_add(1, Ordering::Relaxed)
    ))
}

