fn brew_version(name: &str) -> eyre::Result<Option<String>> {
    let result = Command::new("brew")
        .args(["list", "--formula", "--versions", name])
        .output()?;
    if !result.status.success() {
        return Ok(None);
    }
    Ok(String::from_utf8(result.stdout)?
        .split_whitespace()
        .nth(1)
        .map(str::to_string))
}

