fn known_unmanaged_path(path: &Path, home: &Path) -> bool {
    [
        home.join(".opencode/bin/opencode"),
        home.join(".local/bin/opencode"),
        home.join("bin/opencode"),
        PathBuf::from("/usr/local/bin/opencode"),
    ]
    .iter()
    .any(|known| path == known)
}

